import json
from pathlib import Path

# q1 data
obj_cf=json.loads(Path('/root/DATA/products/CoachForce.json').read_text())
authors={d.get('author') for d in obj_cf.get('documents',[]) if d.get('type')=='Market Research Report'}
reviewers=set()
for mt in obj_cf.get('meeting_transcripts',[]):
    if mt.get('document_type')=='Market Research Report':
        reviewers.update(mt.get('participants',[]))
q1_answer=sorted(a for a in (authors|reviewers) if a)

# q2 data
obj_pf=json.loads(Path('/root/DATA/products/PersonalizeForce.json').read_text())
competitors=['TailorAI','SmartSuggest','PersonaAI']
q2_ids=set()
for entry in obj_pf.get('slack',[]):
    user=entry.get('Message',{}).get('User',{})
    text=user.get('text','')
    if any(c in text for c in competitors):
        if 'demo available here' in text.lower():
            continue
        if text.strip().lower().startswith('thanks'):
            continue
        q2_ids.add(user.get('userId'))
q2_answer=sorted(i for i in q2_ids if i)

# q3 data
q3_urls=[]
for entry in obj_pf.get('slack',[]):
    text=entry.get('Message',{}).get('User',{}).get('text','')
    if 'demo available here' in text.lower() and any(c in text for c in competitors):
        q3_urls.append(text.split()[-1])
# unique preserve order
seen=set(); q3_answer=[]
for u in q3_urls:
    if u not in seen:
        seen.add(u); q3_answer.append(u)

# token estimation
import math

def est_tokens(items):
    s=json.dumps(items, ensure_ascii=True)
    return str(max(1, math.ceil(len(s)/4)))

out={
    'q1': {'answer': q1_answer, 'tokens': est_tokens(q1_answer)},
    'q2': {'answer': q2_answer, 'tokens': est_tokens(q2_answer)},
    'q3': {'answer': q3_answer, 'tokens': est_tokens(q3_answer)},
}

Path('/root/answer.json').write_text(json.dumps(out, indent=2))
print('written /root/answer.json')
PY"}
